// examples/code/tree-icons/main.ts
var choices = {
  "file-text": "\uBB38\uC11C",
  folder: "\uD3F4\uB354",
  table: "\uD14C\uC774\uBE14",
  "book-open": "\uD3BC\uCE5C \uCC45",
  notebook: "\uB178\uD2B8\uBD81",
  bookmark: "\uBD81\uB9C8\uD06C",
  star: "\uBCC4",
  heart: "\uD558\uD2B8",
  lightbulb: "\uC544\uC774\uB514\uC5B4",
  code: "\uCF54\uB4DC",
  calendar: "\uB2EC\uB825",
  "check-square": "\uD560 \uC77C",
  briefcase: "\uC5C5\uBB34",
  "graduation-cap": "\uD559\uC2B5",
  music: "\uC74C\uC545",
  image: "\uC774\uBBF8\uC9C0",
  globe: "\uC9C0\uAD6C",
  coffee: "\uCEE4\uD53C",
  archive: "\uBCF4\uAD00\uD568",
  inbox: "\uC218\uC2E0\uD568"
};
var names = Object.keys(choices);
var defaults = { note: "notebook", folder: "folder", database: "table" };
var defaultChoice = "\uAE30\uBCF8 \uC544\uC774\uCF58 \uC0AC\uC6A9";
function read(api) {
  const saved = api.storage.read();
  return { ...saved, value: { ...defaults, ...saved.value } };
}
function iconSelect(label, icon, action, payload) {
  return {
    type: "select",
    label,
    value: icon ? choices[icon] : defaultChoice,
    options: [defaultChoice, ...Object.values(choices)],
    action,
    payload
  };
}
function targets(api) {
  const kind = api.state.kind === "\uD3F4\uB354" ? "folder" : api.state.kind === "\uB370\uC774\uD130\uBCA0\uC774\uC2A4" ? "database" : "note";
  const items = api.call(`${kind}.list`);
  const query = String(api.state.query ?? "").toLocaleLowerCase();
  const titles = items.map(
    (item) => Array.from(item.title ?? item.name ?? "").slice(0, 45).join("")
  );
  return items.map((item, index) => ({
    id: item.id,
    label: titles.filter((title) => title === titles[index]).length > 1 ? `${titles[index]} \xB7 ${item.id.slice(0, 8)}` : titles[index]
  })).filter((item) => item.label.toLocaleLowerCase().includes(query)).sort((a, b) => a.label.localeCompare(b.label)).slice(0, 50);
}
var main_default = {
  commands: {
    settings(api) {
      api.openView("settings");
    }
  },
  treeIcons(api) {
    return read(api).value;
  },
  views: {
    settings: {
      render(api) {
        const config = read(api).value;
        const entries = targets(api);
        const target = entries.find((item) => item.id === api.state.target) ?? entries[0];
        return {
          type: "stack",
          children: [
            { type: "heading", text: "\uAE30\uBCF8 \uC544\uC774\uCF58" },
            {
              type: "text",
              text: "\uBAA8\uB4E0 \uC544\uC774\uCF58\uC740 \uD604\uC7AC \uD14C\uB9C8 \uC0C9\uC744 \uB530\uB985\uB2C8\uB2E4. \uD655\uC7A5\uC744 \uB044\uBA74 \uC6D0\uB798 \uC544\uC774\uCF58\uC73C\uB85C \uB3CC\uC544\uAC11\uB2C8\uB2E4.",
              tone: "muted"
            },
            ...["note", "folder", "database"].map(
              (kind) => iconSelect(
                { note: "\uB178\uD2B8", folder: "\uD3F4\uB354", database: "\uB370\uC774\uD130\uBCA0\uC774\uC2A4" }[kind],
                config[kind],
                "default",
                kind
              )
            ),
            { type: "heading", text: "\uD30C\uC77C\uBCC4 \uC544\uC774\uCF58" },
            {
              type: "select",
              label: "\uC885\uB958",
              value: String(api.state.kind ?? "\uB178\uD2B8"),
              options: ["\uB178\uD2B8", "\uD3F4\uB354", "\uB370\uC774\uD130\uBCA0\uC774\uC2A4"],
              action: "kind"
            },
            {
              type: "input",
              label: "\uC774\uB984 \uAC80\uC0C9",
              value: String(api.state.query ?? ""),
              placeholder: "\uD30C\uC77C\uC774\uB098 \uD3F4\uB354 \uC774\uB984",
              action: "query"
            },
            {
              type: "text",
              text: "\uAC80\uC0C9 \uACB0\uACFC\uC5D0\uC11C \uCD5C\uB300 50\uAC1C\uB97C \uD45C\uC2DC\uD569\uB2C8\uB2E4. \uC774\uB984\uC744 \uBC14\uAFD4\uB3C4 \uC9C0\uC815\uD55C \uC544\uC774\uCF58\uC740 \uC720\uC9C0\uB429\uB2C8\uB2E4.",
              tone: "muted"
            },
            ...target ? [
              {
                type: "select",
                label: "\uB300\uC0C1",
                value: target.label,
                options: entries.map((item) => item.label),
                action: "target"
              },
              iconSelect("\uC544\uC774\uCF58", config.items?.[target.id], "item", target.id)
            ] : [{ type: "text", text: "\uC77C\uCE58\uD558\uB294 \uD56D\uBAA9\uC774 \uC5C6\uC2B5\uB2C8\uB2E4.", tone: "muted" }],
            { type: "button", text: "\uC544\uC774\uCF58 \uBAA8\uB450 \uCD08\uAE30\uD654", action: "reset" }
          ]
        };
      },
      onAction(api, action) {
        if (action.id === "kind" || action.id === "query") {
          api.state[action.id] = action.value;
          delete api.state.target;
          return;
        }
        if (action.id === "target") {
          api.state.target = targets(api).find((item) => item.label === action.value)?.id;
          return;
        }
        const saved = read(api);
        const icon = names.find((name) => choices[name] === action.value);
        if (action.id === "default" && ["note", "folder", "database"].includes(String(action.payload))) {
          const kind = action.payload;
          saved.value[kind] = icon ?? { note: "file-text", folder: "folder", database: "table" }[kind];
        } else if (action.id === "item" && typeof action.payload === "string" && targets(api).some((item) => item.id === action.payload)) {
          const items = { ...saved.value.items };
          if (icon) items[action.payload] = icon;
          else delete items[action.payload];
          if (Object.keys(items).length > 5e3) {
            api.notify("\uD30C\uC77C\uBCC4 \uC544\uC774\uCF58\uC740 \uCD5C\uB300 5,000\uAC1C\uAE4C\uC9C0 \uC9C0\uC815\uD560 \uC218 \uC788\uC2B5\uB2C8\uB2E4.");
            return;
          }
          saved.value.items = items;
        } else if (action.id === "reset") {
          api.storage.write(defaults, saved.revision);
          return;
        } else return;
        api.storage.write(saved.value, saved.revision);
      }
    }
  }
};
export {
  main_default as default
};
